mapper.select:
select sku, activity_id, activity_count_id, stock_count, stock_count_surplus, applied_consumed
from raffle_activity_sku
where sku = #{sku}

mapper.update:
update raffle_activity_sku
set stock_count_surplus = stock_count - #{consumedAfter},
    applied_consumed = #{consumedAfter},
    update_time = now()
where sku = #{sku}
  and applied_consumed < #{consumedAfter}

mapper.select:
select sku, activity_count_id, stock_count, stock_count_surplus, applied_consumed
from raffle_activity_sku
where activity_id = #{activityId}
